from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

BASE = 'http://localhost:8080'
token = None
request_count = 0
rate_limit_events = 0

def parse_json_bytes(raw):
    try:
        return json.loads(raw.decode('utf-8'))
    except Exception:
        return None

def get_wait(headers, body):
    for k in ('Retry-After', 'retry-after', 'X-Retry-In', 'X-RateLimit-Reset'):
        v = headers.get(k)
        if v:
            try:
                n = float(v)
                # Reset headers may be epoch timestamps; this service documents waits,
                # but handle either representation safely.
                if k.lower().endswith('reset') and n > time.time():
                    n -= time.time()
                return max(0.0, n)
            except ValueError:
                pass
    if isinstance(body, dict):
        for k in ('retry_after', 'retryAfter', 'wait', 'wait_seconds', 'retry_in', 'retry_in_seconds'):
            if k in body:
                try:
                    return max(0.0, float(body[k]))
                except (TypeError, ValueError):
                    pass
    return 1.0

def fetch_token():
    global token, request_count, rate_limit_events
    while True:
        req = Request(BASE + '/token', method='POST')
        try:
            with urlopen(req, timeout=30) as resp:
                request_count += 1
                data = json.load(resp)
                token = data['token']
                return
        except HTTPError as e:
            request_count += 1
            raw = e.read()
            body = parse_json_bytes(raw)
            if e.code == 429:
                rate_limit_events += 1
                wait = get_wait(e.headers, body)
                print(f'token rate-limited; waiting {wait:g}s', file=sys.stderr)
                time.sleep(wait)
            else:
                print(f'token HTTP {e.code}; retrying', file=sys.stderr)
                time.sleep(1)
        except (URLError, TimeoutError, OSError, ValueError, KeyError) as e:
            print(f'token request error {e"'!r}; retrying'"', file=sys.stderr)
            time.sleep(1)

def request_json(path, authenticated=True):
    global token, request_count, rate_limit_events
    if authenticated and token is None:
        fetch_token()
    while True:
        headers = {}
        if authenticated:
            headers['Authorization'] = 'Bearer ' + token
        req = Request(BASE + path, headers=headers, method='GET')
        try:
            with urlopen(req, timeout=30) as resp:
                request_count += 1
                return json.load(resp)
        except HTTPError as e:
            request_count += 1
            raw = e.read()
            body = parse_json_bytes(raw)
            if e.code == 401 and authenticated:
                print(f'{path}: token rejected; refreshing', file=sys.stderr)
                fetch_token()
                continue
            if e.code == 429:
                rate_limit_events += 1
                wait = get_wait(e.headers, body)
                print(f'{path}: rate-limited; waiting {wait:g}s', file=sys.stderr)
                time.sleep(wait)
                continue
            print(f'{path}: HTTP {e.code}; retrying', file=sys.stderr)
            time.sleep(1)
        except (URLError, TimeoutError, OSError, ValueError) as e:
            print(f'{path}: request/parse error {e"'!r}; retrying'"', file=sys.stderr)
            time.sleep(1)

fetch_token()
orders = {}
duplicates = 0
path = '/orders?page=1'
page_count = 0
while path:
    data = request_json(path)
    page_count += 1
    items = data.get('items')
    if not isinstance(items, list):
        print(f'{path}: malformed items; retrying', file=sys.stderr)
        continue
    for order in items:
        oid = order.get('id')
        if oid in orders:
            duplicates += 1
        else:
            orders[oid] = order
    path = data.get('next')
    if path is not None and not isinstance(path, str):
        print('malformed next; retrying current page', file=sys.stderr)
        path = f\"/orders?page={data['page']}\"

start = datetime(2025, 3, 1, tzinfo=timezone.utc)
end = datetime(2025, 6, 1, tzinfo=timezone.utc)
customer_cache = {}
qualifying = []
for order in orders.values():
    if order.get('status') "'!= '"'shipped':
        continue
    try:
        placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    except Exception as e:
        print(f\"{order.get('id')}: bad timestamp {e"'!r}; retrying source page is not possible", file=sys.stderr)
        raise
    if not (start <= placed < end):
        continue
    cid = order['"'customer_id']
    if cid not in customer_cache:
        customer_cache[cid] = request_json('/customers/' + cid)
    qualifying.append((order, customer_cache[cid], placed))

by_region = {r: 0 for r in ('north', 'south', 'east', 'west')}
for order, customer, placed in qualifying:
    amount = Decimal(order['amount_cents'])
    pct = Decimal(customer['discount_pct'])
    discounted = (amount * (Decimal(100) - pct) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(discounted)
result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print(json.dumps(result, sort_keys=True))
print(f'pages={page_count} unique_orders={len(orders)} customers_cached={len(customer_cache)} requests={request_count} rate_limit_events={rate_limit_events}', file=sys.stderr)
